export const modes=['Horde','Arena','Boss','Custom'];
export const defaults=()=>({schema:1,title:'My Tatari tierlist',gameMode:'Horde',tier:4,notes:'',rows:['S','A','B','C','D'].map((label,i)=>({label,color:['#ff9c95','#ffc68b','#ffe17a','#bce594','#a7d9f3'][i],units:[]}))});
export function cleanList(raw,units){if(!raw||raw.schema!==1||!modes.includes(raw.gameMode)||![1,2,3,4].includes(raw.tier)||!Array.isArray(raw.rows)||raw.rows.length!==5)throw Error('This tierlist link is invalid.');const ids=new Set(units.map(u=>u.id)),seen=new Set();return {schema:1,title:String(raw.title||'My Tatari tierlist').slice(0,80),gameMode:raw.gameMode,tier:raw.tier,notes:String(raw.notes||'').slice(0,500),rows:raw.rows.map(r=>{if(!r||!/^#[0-9a-f]{6}$/i.test(r.color)||!Array.isArray(r.units))throw Error('Invalid tierlist row.');return {label:String(r.label||'?').slice(0,16),color:r.color,units:r.units.filter(id=>{if(!ids.has(id)||seen.has(id))return false;seen.add(id);return true})}})}}
export function moveUnit(state,id,row,index){state.rows.forEach(r=>r.units=r.units.filter(u=>u!==id));if(row>=0){const list=state.rows[row].units;list.splice(index===undefined?list.length:Math.max(0,Math.min(index,list.length)),0,id)}}
export const formFor=(unit,tier)=>unit.forms.find(f=>f.evolution===tier)||unit.forms.at(-1);
export function encodeList(s){return btoa(String.fromCharCode(...new TextEncoder().encode(JSON.stringify(s))))}
export function decodeList(s){if(s.length>16000)throw Error('Tierlist link is too long.');return JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0))))}
